	t.Run("GetCompressionType", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &KafkaAdvancedConfig{}
		var expected *KafkaAdvancedConfigCompressionType
		obj.CompressionType = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetCompressionType(), "getter should return the property value")
	})

